// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Initialize EntryPointContract
  *
  * guarantee CR01_Rx_Init
  *   FirewallRx_Req_Init: malformed count starts at zero; attack status DataPort initialized to OK.
  * @param malformedCount post-state state variable
  * @param api_AttackStatusRx outgoing data port
  */
pub fn initialize_CR01_Rx_Init(
  malformedCount: i32,
  api_AttackStatusRx: SW::AttackStatus) -> bool
{
  (malformedCount == 0i32) &
    (api_AttackStatusRx == SW::AttackStatus::OK)
}

/** IEP-Guar: Initialize Entrypoint for FirewallRx
  *
  * @param malformedCount post-state state variable
  * @param api_EthernetFramesRxOut outgoing event data port
  * @param api_AttackStatusRx outgoing data port
  */
pub fn initialize_IEP_Guar(
  malformedCount: i32,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusRx: SW::AttackStatus) -> bool
{
  initialize_CR01_Rx_Init(malformedCount, api_AttackStatusRx)
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param malformedCount post-state state variable
  * @param api_EthernetFramesRxOut outgoing event data port
  * @param api_AttackStatusRx outgoing data port
  */
pub fn initialize_IEP_Post(
  malformedCount: i32,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusRx: SW::AttackStatus) -> bool
{
  initialize_IEP_Guar(malformedCount, api_EthernetFramesRxOut, api_AttackStatusRx)
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_1
  *   1.1 firewall: no frame in RxOut if no frame in RxIn (RC_INSPECTA_00-HLR-1) The firewall shall not have any frame in RxOut if there are no frame in RxIn.
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_1_guarantee(
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    !(api_EthernetFramesRxIn.is_some()),
    api_EthernetFramesRxOut.is_none())
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_2
  *   1.2 firewall: drop malformed frames (RC_INSPECTA_00-HLR-1) The firewall shall drop any frame that is malformed.
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_2_guarantee(
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesRxIn.is_some(),
    impliesL!(
      GumboLib::isMalformedFrame(api_EthernetFramesRxIn.unwrap()),
      api_EthernetFramesRxOut.is_none()))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_4
  *   1.4 firewall: drop ipv6 frames (RC_INSPECTA_00-HLR-2) The firewall shall drop any frame that is type ipv6.
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_4_guarantee(
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesRxIn.is_some(),
    impliesL!(
      GumboLib::isIPV6(api_EthernetFramesRxIn.unwrap()),
      api_EthernetFramesRxOut.is_none()))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_6
  *   1.6 firewall: drop RxIn ipv4 arp frames (RC_INSPECTA_00-HLR-4) The firewall shall drop any frame from RxIn that is an Ipv4 frame whose protocol is ARP.
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_6_guarantee(
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesRxIn.is_some(),
    impliesL!(
      GumboLib::isARP(api_EthernetFramesRxIn.unwrap()),
      api_EthernetFramesRxOut.is_none()))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_8
  *   1.8 firewall: drop RxIn ipv4 tcp frames with unexpected ports (RC_INSPECTA_00-HLR-6) The firewall shall drop any frame from RxIn that is an Ipv4 frame whose protocol is TCP and whose port is not defined in the port whitelist.
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_8_guarantee(
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesRxIn.is_some(),
    impliesL!(
      GumboLib::isIPV4(api_EthernetFramesRxIn.unwrap()) & GumboLib::isTCP(api_EthernetFramesRxIn.unwrap()) &
        !(GumboLib::isPortWhitelisted(api_EthernetFramesRxIn.unwrap())),
      api_EthernetFramesRxOut.is_none()))
}

/** Compute Entrypoint Contract
  *
  * guarantee RC_INSPECTA_00_HLR_9
  *   1.9 firewall: copy through allowed tcp port packets (RC_INSPECTA_00-HLR-8; revised CR-01: applies in Normal mode only) In Normal mode, the firewall shall copy any frame from RxIn that is a non-malformed Ipv4 frame with the TCP protocol and whose port is defined in the port whitelist to RxOut.
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_RC_INSPECTA_00_HLR_9_guarantee(
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    api_EthernetFramesRxIn.is_some(),
    impliesL!(
      (api_CurrentMode == SW::Mode::Normal) &
        GumboLib::isIPV4(api_EthernetFramesRxIn.unwrap()) &
        GumboLib::isTCP(api_EthernetFramesRxIn.unwrap()) &
        GumboLib::isPortWhitelisted(api_EthernetFramesRxIn.unwrap()) &
        !(GumboLib::isMalformedFrame(api_EthernetFramesRxIn.unwrap())),
      api_EthernetFramesRxOut.is_some() &&
        (api_EthernetFramesRxIn.unwrap() == api_EthernetFramesRxOut.unwrap())))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_Rx_ModeGate
  *   FirewallRx_Req_ModeGate (CR-01): in Init and RTL modes, drop every frame — no output regardless of input.
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesRxOut outgoing event data port
  */
pub fn compute_spec_CR01_Rx_ModeGate_guarantee(
  api_CurrentMode: SW::Mode,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    !(api_CurrentMode == SW::Mode::Normal),
    api_EthernetFramesRxOut.is_none())
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_Rx_Count
  *   FirewallRx_Req_Count (CR-01): cumulative malformed-frame count since initialization, incremented on each malformed received frame, saturating at 6; mode-independent.
  * @param In_malformedCount pre-state state variable
  * @param malformedCount post-state state variable
  * @param api_EthernetFramesRxIn incoming event data port
  */
pub fn compute_spec_CR01_Rx_Count_guarantee(
  In_malformedCount: i32,
  malformedCount: i32,
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  (implies!(
    api_EthernetFramesRxIn.is_some() && GumboLib::isMalformedFrame(api_EthernetFramesRxIn.unwrap()) &&
      (In_malformedCount < 6i32),
    (malformedCount == In_malformedCount + 1i32))) &
    (implies!(
      api_EthernetFramesRxIn.is_some() && GumboLib::isMalformedFrame(api_EthernetFramesRxIn.unwrap()) &&
        (In_malformedCount >= 6i32),
      (malformedCount == In_malformedCount))) &
    (implies!(
      !(api_EthernetFramesRxIn.is_some()) || !(GumboLib::isMalformedFrame(api_EthernetFramesRxIn.unwrap())),
      (malformedCount == In_malformedCount)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CR01_Rx_Detect
  *   FirewallRx_Req_Detect (CR-01): report Attack when the (post-update) malformed count exceeds five, OK otherwise.
  * @param malformedCount post-state state variable
  * @param api_AttackStatusRx outgoing data port
  */
pub fn compute_spec_CR01_Rx_Detect_guarantee(
  malformedCount: i32,
  api_AttackStatusRx: SW::AttackStatus) -> bool
{
  (implies!(
    (malformedCount > 5i32),
    (api_AttackStatusRx == SW::AttackStatus::Attack))) &
    (implies!(
      (malformedCount <= 5i32),
      (api_AttackStatusRx == SW::AttackStatus::OK)))
}

/** CEP-T-Guar: Top-level guarantee contracts for FirewallRx's compute entrypoint
  *
  * @param In_malformedCount pre-state state variable
  * @param malformedCount post-state state variable
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesRxOut outgoing event data port
  * @param api_AttackStatusRx outgoing data port
  */
pub fn compute_CEP_T_Guar(
  In_malformedCount: i32,
  malformedCount: i32,
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusRx: SW::AttackStatus) -> bool
{
  let r0: bool = compute_spec_RC_INSPECTA_00_HLR_1_guarantee(api_EthernetFramesRxIn, api_EthernetFramesRxOut);
  let r1: bool = compute_spec_RC_INSPECTA_00_HLR_2_guarantee(api_EthernetFramesRxIn, api_EthernetFramesRxOut);
  let r2: bool = compute_spec_RC_INSPECTA_00_HLR_4_guarantee(api_EthernetFramesRxIn, api_EthernetFramesRxOut);
  let r3: bool = compute_spec_RC_INSPECTA_00_HLR_6_guarantee(api_EthernetFramesRxIn, api_EthernetFramesRxOut);
  let r4: bool = compute_spec_RC_INSPECTA_00_HLR_8_guarantee(api_EthernetFramesRxIn, api_EthernetFramesRxOut);
  let r5: bool = compute_spec_RC_INSPECTA_00_HLR_9_guarantee(api_EthernetFramesRxIn, api_CurrentMode, api_EthernetFramesRxOut);
  let r6: bool = compute_spec_CR01_Rx_ModeGate_guarantee(api_CurrentMode, api_EthernetFramesRxOut);
  let r7: bool = compute_spec_CR01_Rx_Count_guarantee(In_malformedCount, malformedCount, api_EthernetFramesRxIn);
  let r8: bool = compute_spec_CR01_Rx_Detect_guarantee(malformedCount, api_AttackStatusRx);

  return r0 && r1 && r2 && r3 && r4 && r5 && r6 && r7 && r8;
}

/** CEP-Post: Compute Entrypoint Post-Condition for FirewallRx
  *
  * @param In_malformedCount pre-state state variable
  * @param malformedCount post-state state variable
  * @param api_EthernetFramesRxIn incoming event data port
  * @param api_CurrentMode incoming data port
  * @param api_EthernetFramesRxOut outgoing event data port
  * @param api_AttackStatusRx outgoing data port
  */
pub fn compute_CEP_Post(
  In_malformedCount: i32,
  malformedCount: i32,
  api_EthernetFramesRxIn: Option<SW::StructuredEthernetMessage_i>,
  api_CurrentMode: SW::Mode,
  api_EthernetFramesRxOut: Option<SW::StructuredEthernetMessage_i>,
  api_AttackStatusRx: SW::AttackStatus) -> bool
{
  // CEP-Guar: guarantee clauses of FirewallRx's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(In_malformedCount, malformedCount, api_EthernetFramesRxIn, api_CurrentMode, api_EthernetFramesRxOut, api_AttackStatusRx);

  return r0;
}
